
const places=[{id:'restaurant',icon:'🍔',name:'Restaurant',desc:'Order food politely',line:'Hi! Are you ready to order?',mm:'မှာယူဖို့ အဆင်သင့်ဖြစ်ပြီလား။',q:'How do you order a sandwich?',opts:['I would like a chicken sandwich, please.','The train is late.','I am going home yesterday.'],correct:0,reply:'Of course! Would you like a drink?'},{id:'airport',icon:'✈️',name:'Airport',desc:'Check in for a flight',line:'May I see your passport, please?',mm:'သင့်နိုင်ငံကူးလက်မှတ် ပြပေးပါ။',q:'What is a polite response?',opts:['No, I eat breakfast.','Certainly. Here it is.','I do not like museums.'],correct:1,reply:'Thank you. Are you checking any bags?'},{id:'workplace',icon:'💼',name:'Workplace',desc:'Talk with coworkers',line:'Could you help me with this report?',mm:'ဒီအစီရင်ခံစာအတွက် ကူညီပေးနိုင်မလား။',q:'How can you politely agree?',opts:['I never work.','Yesterday is sunny.','Sure, I would be happy to help.'],correct:2,reply:'Thanks! I really appreciate it.'},{id:'shopping',icon:'🛍️',name:'Shopping',desc:'Ask about prices',line:'Can I help you find anything?',mm:'တစ်ခုခုရှာဖို့ ကူညီပေးရမလား။',q:'How do you ask for a size?',opts:['Do you have this in a medium?','I am driving tomorrow.','My coffee is cold.'],correct:0,reply:'Let me check for you.'},{id:'hospital',icon:'🏥',name:'Clinic',desc:'Make an appointment',line:'What brings you in today?',mm:'ဒီနေ့ ဘာကိစ္စနဲ့ လာတာလဲ။',q:'What is an appropriate reply?',opts:['I am going shopping.','I have had a headache since yesterday.','The movie starts at seven.'],correct:1,reply:'I see. Let me ask a few questions.'},{id:'train',icon:'🚆',name:'Train Station',desc:'Ask for directions',line:'Where are you traveling today?',mm:'ဒီနေ့ ဘယ်ကို ခရီးသွားမှာလဲ။',q:'Choose a natural response.',opts:['I am very delicious.','I ate my ticket.','I am going to Washington, D.C.'],correct:2,reply:'Great. The next train leaves at 10:30.'}];
const lessons=[{name:'Greetings & Introductions',level:'Starter',word:'Nice to meet you.',mm:'တွေ့ရတာ ဝမ်းသာပါတယ်။',text:'When you meet someone for the first time, say “Nice to meet you.”',question:'What do you say when meeting someone new?',opts:['Nice to meet you.','See you yesterday.','I am a sandwich.'],correct:0,writing:'Write a short introduction: My name is ... I live in ...'},{name:'At the Restaurant',level:'Beginner',word:'I would like to order.',mm:'ကျွန်တော်/ကျွန်မ မှာယူချင်ပါတယ်။',text:'Use “I would like...” to order politely. You can also say “Could I have...?”',question:'Which sentence is polite?',opts:['Give food now!','Could I have some water, please?','Water yesterday went.'],correct:1,writing:'Write a polite sentence ordering a drink or meal.'},{name:'Asking for Directions',level:'Elementary',word:'Could you tell me how to get there?',mm:'အဲဒီနေရာကို ဘယ်လိုသွားရမလဲ ပြောပြပေးနိုင်မလား။',text:'Start with “Excuse me” and ask for directions politely.',question:'How do you ask for directions?',opts:['You are a road.','I will eat the bus.','Excuse me, where is the train station?'],correct:2,writing:'Write a polite question asking where the library is.'},{name:'At Work',level:'Intermediate',word:'Could we go over the details?',mm:'အသေးစိတ်အချက်အလက်တွေကို ပြန်ဆွေးနွေးလို့ရမလား။',text:'“Go over” means to review or discuss something carefully.',question:'What does “go over the report” mean?',opts:['Review the report','Jump over the report','Delete the report'],correct:0,writing:'Write a polite message asking your coworker to review a report.'}];
const expressions=[['What’s up?','ဘာထူးလဲ။','Informal greeting among friends.'],['No worries.','ကိစ္စမရှိပါဘူး။','Friendly response to an apology or thanks.'],['I’m down.','ကျွန်တော်လည်း ပါမယ်။','Casual agreement to a plan.'],['Break a leg!','အောင်မြင်ပါစေ။','Encouragement before a performance.'],['Hit the road.','ခရီးစထွက်မယ်။','Informal expression for leaving on a trip.'],['Sounds good.','ကောင်းပါတယ်။','Natural agreement in everyday conversation.']];
const pages=[['home','🏠','Home'],['academy','🎓','Academy'],['world','🗺️','World'],['speak','🎙️','Speak'],['profile','👤','Profile']];let state=JSON.parse(localStorage.getItem('eausa_progress')||'{"xp":0,"completed":[],"missions":[],"writing":{}}');let page='home',selectedLesson=0,selectedPlace=0,choice=-1,missionChoice=-1,feedback='',missionFeedback='',expr=0,recognized='';function save(){localStorage.setItem('eausa_progress',JSON.stringify(state));document.getElementById('xp').textContent=state.xp}function esc(s){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}function nav(p){page=p;feedback='';missionFeedback='';render();window.scrollTo(0,0)}function speak(s){if(!('speechSynthesis'in window)){alert('Speech synthesis is not available in this browser.');return}speechSynthesis.cancel();let u=new SpeechSynthesisUtterance(s);u.lang='en-US';u.rate=.85;speechSynthesis.speak(u)}function award(key,amount){if(!state.completed.includes(key)){state.completed.push(key);state.xp+=amount;save();return true}return false}function header(title,sub){return `<h1>${title}</h1><p class="muted">${sub}</p>`}function render(){document.getElementById('nav').innerHTML=pages.map(([id,icon,name])=>`<button class="${page===id?'active':''}" onclick="nav('${id}')">${icon} ${name}</button>`).join('');document.getElementById('bottom').innerHTML=pages.map(([id,icon,name])=>`<button class="${page===id?'active':''}" onclick="nav('${id}')"><span>${icon}</span>${name}</button>`).join('');save();let a=document.getElementById('app');if(page==='home'){a.innerHTML=`<section class="hero"><div><span class="tag">✨ Your English journey starts here</span><h1>Explore America.<br>Speak with confidence.</h1><p>သင်ခန်းစာတွေ လေ့လာ၊ အမေရိကန်မြို့ထဲ စူးစမ်း၊ နေ့စဉ်သုံး အင်္ဂလိပ်စကားကို လက်တွေ့လေ့ကျင့်ပါ။</p><button class="btn white" onclick="nav('world')">🗺️ Explore the World →</button></div><div class="art">🏙️</div></section><h2 class="section">Choose your adventure</h2><div class="grid"><div class="card"><div class="big">🎓</div><h3>English Academy</h3><p class="muted">Listening, Reading, Writing & Speaking lessons</p><button class="btn" onclick="nav('academy')">Start Learning</button></div><div class="card"><div class="big">🌎</div><h3>Adventure World</h3><p class="muted">Real-life conversations across America</p><button class="btn" onclick="nav('world')">Explore Missions</button></div><div class="card"><div class="big">🎙️</div><h3>Speaking Studio</h3><p class="muted">Practice American English out loud</p><button class="btn" onclick="nav('speak')">Practice Speaking</button></div></div><h2 class="section">Today's American Expressions</h2><div class="card"><span class="tag">Daily English</span><div class="expression" style="margin:12px 0">${esc(expressions[expr][0])}</div><p>${esc(expressions[expr][1])}</p><p class="muted">${esc(expressions[expr][2])}</p><div class="row"><button class="btn secondary" onclick="speak(expressions[expr][0])">🔊 Listen</button><button class="btn secondary" onclick="expr=(expr+1)%expressions.length;render()">Next Expression →</button></div></div>`}
if(page==='academy'){a.innerHTML=header('🎓 English Academy','Beginner to Pro • Four core skills • မြန်မာလိုရှင်းပြချက်များ')+`<div class="grid">${lessons.map((l,i)=>`<div class="card"><span class="tag">${l.level}</span><h3>${esc(l.name)}</h3><p class="muted">🔊 Listen • 📖 Read • ✍️ Write • 🎙️ Speak</p><p>${state.completed.includes('lesson'+i)?'✅ Completed':'⭐ +40 XP'}</p><button class="btn" onclick="selectedLesson=${i};choice=-1;feedback='';page='lesson';render()">Open Lesson →</button></div>`).join('')}</div><h2 class="section">Learning Path</h2><div class="card">${['Starter · Pre-A1','Beginner · A1','Elementary · A2','Intermediate · B1','Upper Intermediate · B2','Advanced · C1','Expert · C2','Pro · Mastery'].map((x,i)=>`<div class="level"><strong>${i+1}. ${x}</strong><span class="tag">${i<4?'Sample available':'Coming in full course'}</span></div>`).join('')}</div>`}
if(page==='lesson'){let l=lessons[selectedLesson];a.innerHTML=`<div class="lesson"><button class="btn secondary" onclick="nav('academy')">← Academy</button><h1>${esc(l.name)}</h1><span class="tag">${l.level} • Lesson ${selectedLesson+1}</span><div class="card" style="margin-top:15px"><h2>🔊 Listen & Repeat</h2><h2>${esc(l.word)}</h2><p>${esc(l.mm)}</p><div class="row"><button class="btn" onclick="speak(lessons[selectedLesson].word)">🔊 Play American English</button><button class="btn secondary" onclick="speak(lessons[selectedLesson].word)">↻ Repeat</button></div></div><div class="card" style="margin-top:14px"><h2>📖 Reading</h2><p>${esc(l.text)}</p><button class="btn secondary" onclick="speak(lessons[selectedLesson].text)">🔊 Read aloud</button></div><div class="card" style="margin-top:14px"><h2>🧠 Quick Quiz</h2><p>${esc(l.question)}</p><div class="choices">${l.opts.map((o,i)=>`<button class="choice ${choice===i?'selected':''}" onclick="choice=${i};feedback='';render()">${String.fromCharCode(65+i)}. ${esc(o)}</button>`).join('')}</div><button class="btn" onclick="checkLesson()">Check Answer</button>${feedback?`<div class="feedback ${feedback.startsWith('Try')?'bad':''}">${feedback}</div>`:''}</div><div class="card" style="margin-top:14px"><h2>✍️ Writing Workshop</h2><p>${esc(l.writing)}</p><textarea class="field" id="writing" placeholder="Write your English here...">${esc(state.writing['lesson'+selectedLesson]||'')}</textarea><button class="btn secondary" onclick="state.writing['lesson'+selectedLesson]=document.getElementById('writing').value;save();alert('Writing saved on this device. This prototype does not automatically grade free-form writing.')">💾 Save Writing</button></div><div class="card" style="margin-top:14px"><h2>🎙️ Speaking</h2><p>Listen, then repeat: <strong>${esc(l.word)}</strong></p><button class="btn secondary" onclick="speak(lessons[selectedLesson].word)">🔊 Hear sentence</button> <button class="btn" onclick="listen()">🎙️ Try microphone</button><p class="muted" id="speechResult">Microphone recognition depends on your browser and permissions.</p></div></div>`}
if(page==='world'){a.innerHTML=header('🗺️ American Adventure World','Choose a location. Meet a character. Complete a real-life English mission.')+`<div class="world">${places.map((p,i)=>`<button class="place" onclick="selectedPlace=${i};missionChoice=-1;missionFeedback='';page='mission';render()"><span class="emoji">${p.icon}</span><strong>${p.name}</strong><small>${p.desc}</small><p>${state.missions.includes(p.id)?'🏆 Mission completed':'🎯 Play mission →'}</p></button>`).join('')}</div><div class="notice">🌟 More locations and difficulty levels will be added in the full curriculum. The six locations above are playable sample missions.</div>`}
if(page==='mission'){let p=places[selectedPlace];a.innerHTML=`<div class="lesson"><button class="btn secondary" onclick="nav('world')">← Adventure World</button><h1>${p.icon} ${p.name} Mission</h1><span class="tag">Real-Life English • +30 XP</span><div class="card" style="margin-top:15px"><div class="big">${p.icon} 🧑‍💼</div><h2>Character says:</h2><div class="dialogue"><h2>“${esc(p.line)}”</h2><p class="muted">${esc(p.mm)}</p></div><button class="btn secondary" onclick="speak(places[selectedPlace].line)">🔊 Listen to character</button></div><div class="card" style="margin-top:14px"><h2>🎯 Your turn</h2><p>${esc(p.q)}</p><div class="choices">${p.opts.map((o,i)=>`<button class="choice ${missionChoice===i?'selected':''}" onclick="missionChoice=${i};missionFeedback='';render()">${String.fromCharCode(65+i)}. ${esc(o)}</button>`).join('')}</div><button class="btn" onclick="checkMission()">Submit Answer</button>${missionFeedback?`<div class="feedback ${missionFeedback.startsWith('Try')?'bad':''}">${missionFeedback}</div>`:''}</div></div>`}
if(page==='speak'){a.innerHTML=header('🎙️ Speaking Studio','Listen and repeat • American English practice')+`<div class="grid">${['Nice to meet you.','Could I have a coffee, please?','Can you tell me how to get there?','I would be happy to help.','Could we schedule a meeting?','Thank you. I really appreciate it.'].map((s,i)=>`<div class="card"><span class="tag">Practice ${i+1}</span><h3>${s}</h3><div class="row"><button class="btn secondary" onclick="speak(${JSON.stringify(s).replace(/"/g,'&quot;')})">🔊 Listen</button><button class="btn" onclick="listen()">🎙️ Speak</button></div></div>`).join('')}</div><div class="card"><h3>Microphone feedback</h3><p id="speechResult">Click Speak, allow microphone access, and try a sentence. Recognized words are shown here when supported.</p><p class="notice">Speech recognition is browser-dependent and may use an online service. This prototype shows recognized words; it does not calculate a pronunciation score.</p></div>`}
if(page==='profile'){a.innerHTML=header('👤 My Learning Journey','Your achievements are stored locally in this browser.')+`<div class="grid"><div class="card"><div class="big">⭐</div><div class="stat">${state.xp}</div><strong>Total XP</strong></div><div class="card"><div class="big">🎓</div><div class="stat">${state.completed.filter(x=>x.startsWith('lesson')).length} / ${lessons.length}</div><strong>Sample Lessons</strong></div><div class="card"><div class="big">🏆</div><div class="stat">${state.missions.length} / ${places.length}</div><strong>World Missions</strong></div></div><div class="card"><h2>Learning Progress</h2><p>Academy Lessons</p><div class="bar"><div style="width:${100*state.completed.filter(x=>x.startsWith('lesson')).length/lessons.length}%"></div></div><p>Adventure Missions</p><div class="bar"><div style="width:${100*state.missions.length/places.length}%"></div></div><p class="muted">These numbers describe only this prototype, not an official English proficiency score.</p><button class="btn secondary" onclick="if(confirm('Reset all local prototype progress?')){state={xp:0,completed:[],missions:[],writing:{}};save();render()}">Reset Prototype Progress</button></div>`}
}
function checkLesson(){if(choice<0){feedback='Choose an answer first.';render();return}let l=lessons[selectedLesson];if(choice===l.correct){let first=award('lesson'+selectedLesson,40);feedback='✅ Correct! '+(first?'You earned 40 XP.':'You already completed this lesson.')}else feedback='Try again. Read the lesson and choose the most natural English sentence.';render()}
function checkMission(){if(missionChoice<0){missionFeedback='Choose an answer first.';render();return}let p=places[selectedPlace];if(missionChoice===p.correct){let first=!state.missions.includes(p.id);if(first){state.missions.push(p.id);state.xp+=30;save()}missionFeedback='🎉 Mission complete! '+(first?'+30 XP. ':'')+'Character replies: “'+esc(p.reply)+'”'}else missionFeedback='Try again. Think about what would sound polite and natural in this situation.';render()}
function listen(){let R=window.SpeechRecognition||window.webkitSpeechRecognition;let el=document.getElementById('speechResult');if(!R){if(el)el.textContent='Speech recognition is unavailable in this browser. Try a supported browser or practice by listening and repeating.';return}let r=new R();r.lang='en-US';r.interimResults=false;r.maxAlternatives=1;r.onresult=e=>{let t=e.results[0][0].transcript;let node=document.getElementById('speechResult');if(node)node.textContent='You said: '+t+' (transcription only; not a pronunciation grade)'};r.onerror=e=>{let node=document.getElementById('speechResult');if(node)node.textContent='Microphone error: '+e.error};r.start();if(el)el.textContent='Listening... Please speak now.'}
render();
